({
  _ensureInitialized() {
    if (!this.data || typeof this.data !== 'object') {
      this.data = {};
    }
    if (!this.data.items || typeof this.data.items !== 'object' || Array.isArray(this.data.items)) {
      this.data.items = {};
    }
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === 'object', "State data must be an object");
    this.invariant(this.data.items && typeof this.data.items === 'object' && !Array.isArray(this.data.items), "Items repository must be an object map");

    for (const [key, item] of Object.entries(this.data.items)) {
      this.invariant(typeof key === 'string' && key.length > 0, "Item map key must be a non-empty string");
      this.invariant(item && typeof item === 'object', "Item record must be an object");
      this.invariant(item.id === key, "Item id must match repository key");
      this.invariant(typeof item.name === 'string' && item.name.length > 0, "Item name must be a non-empty string");
      this.invariant(typeof item.qty === 'number' && item.qty >= 0 && Number.isFinite(item.qty), "Item quantity must be a non-negative finite number");
      this.invariant(typeof item.price === 'number' && item.price >= 0 && Number.isFinite(item.price), "Item price must be a non-negative finite number");
    }
  },

  init(msg) {
    this._ensureInitialized();
    this._checkInvariants();
    return { status: "initialized" };
  },

  addItem(msg) {
    this._ensureInitialized();

    const payload = (msg && msg.payload) || {};
    const { id, name, qty, price } = payload;

    this.ensure(typeof id === 'string' && id.trim().length > 0, "Item id must be a non-empty string");
    this.ensure(typeof name === 'string' && name.trim().length > 0, "Item name must be a non-empty string");
    this.ensure(typeof qty === 'number' && qty > 0 && Number.isFinite(qty), "Item quantity must be a positive finite number");
    this.ensure(typeof price === 'number' && price >= 0 && Number.isFinite(price), "Item price must be a non-negative finite number");

    const cleanId = id.trim();
    const cleanName = name.trim();
    const existing = this.data.items[cleanId];

    if (existing) {
      existing.qty += qty;
      existing.name = cleanName;
      existing.price = price;
    } else {
      this.data.items[cleanId] = {
        id: cleanId,
        name: cleanName,
        qty,
        price
      };
    }

    this._checkInvariants();
    this.changed("items", this.data.items);

    const saved = this.data.items[cleanId];
    this.ensure(saved && saved.qty >= qty, "Item must be successfully stored with updated quantity");

    return { ...saved };
  },

  removeItem(msg) {
    this._ensureInitialized();

    const payload = (msg && msg.payload) || {};
    const { id, qty } = payload;

    this.ensure(typeof id === 'string' && id.trim().length > 0, "Item id must be a non-empty string");
    this.ensure(typeof qty === 'number' && qty > 0 && Number.isFinite(qty), "Quantity to remove must be a positive finite number");

    const cleanId = id.trim();
    const existing = this.data.items[cleanId];

    this.ensure(existing !== undefined, "Item not found in inventory");
    this.ensure(existing.qty >= qty, "Insufficient inventory quantity to remove");

    existing.qty -= qty;

    this._checkInvariants();
    this.changed("items", this.data.items);

    const updated = this.data.items[cleanId];
    this.ensure(updated && updated.qty >= 0, "Item quantity must remain valid after removal");

    return { ...updated };
  },

  searchItems(msg) {
    this._ensureInitialized();

    const payload = (msg && msg.payload) || {};
    const { query, inStockOnly } = payload;

    this.ensure(query === undefined || typeof query === 'string', "Query must be a string when provided");
    this.ensure(inStockOnly === undefined || typeof inStockOnly === 'boolean', "inStockOnly must be a boolean when provided");

    let results = Object.values(this.data.items);

    if (typeof query === 'string' && query.trim().length > 0) {
      const q = query.trim().toLowerCase();
      results = results.filter(item =>
        item.id.toLowerCase().includes(q) ||
        item.name.toLowerCase().includes(q)
      );
    }

    if (inStockOnly) {
      results = results.filter(item => item.qty > 0);
    }

    const output = results.map(item => ({ ...item }));
    this.ensure(Array.isArray(output), "Search result must be an array");

    return output;
  },

  listItems(msg) {
    this._ensureInitialized();

    const payload = (msg && msg.payload) || {};
    const offset = payload.offset !== undefined ? payload.offset : 0;
    const limit = payload.limit !== undefined ? payload.limit : 50;

    this.ensure(typeof offset === 'number' && offset >= 0 && Number.isInteger(offset), "Offset must be a non-negative integer");
    this.ensure(typeof limit === 'number' && limit > 0 && Number.isInteger(limit), "Limit must be a positive integer");

    const allItems = Object.values(this.data.items);
    const total = allItems.length;
    const page = allItems.slice(offset, offset + limit).map(item => ({ ...item }));

    const result = {
      items: page,
      total,
      offset,
      limit
    };

    this.ensure(Array.isArray(result.items), "Listing must return an items array");
    this.ensure(typeof result.total === 'number' && result.total >= 0, "Listing must report valid total count");

    return result;
  },

  getValuation(msg) {
    this._ensureInitialized();

    const allItems = Object.values(this.data.items);
    const totalUniqueItems = allItems.length;
    let totalQuantity = 0;
    let totalValue = 0;

    for (const item of allItems) {
      totalQuantity += item.qty;
      totalValue += (item.qty * item.price);
    }

    const valuation = {
      totalUniqueItems,
      totalQuantity,
      totalValue: Number(totalValue.toFixed(2))
    };

    this.ensure(typeof valuation.totalValue === 'number' && valuation.totalValue >= 0 && Number.isFinite(valuation.totalValue), "Valuation total value must be a non-negative finite number");
    this.ensure(typeof valuation.totalQuantity === 'number' && valuation.totalQuantity >= 0, "Valuation total quantity must be non-negative");

    return valuation;
  }
})
